package main

import (
	"bufio"
	"encoding/json"
	"net"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func load(t *testing.T, name string) map[string]any {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatal(err)
	}
	var c map[string]any
	if err := json.Unmarshal(b, &c); err != nil {
		t.Fatal(err)
	}
	return c
}

// Configs generated by the app's real buildConfig must pass.
func TestAcceptsAppConfigs(t *testing.T) {
	for _, f := range []string{"auto.json", "vless_ai.json", "json_import.json"} {
		if err := validate(load(t, f)); err != nil {
			t.Errorf("%s rejected: %v", f, err)
		}
	}
}

// Anything that would let a root core touch files or listen publicly must fail.
func TestRejectsDangerousConfigs(t *testing.T) {
	cases := map[string]func(c map[string]any){
		"log output file": func(c map[string]any) { c["log"].(map[string]any)["output"] = "/etc/sudoers" },
		"extra top-level": func(c map[string]any) { c["services"] = []any{} },
		"cache file": func(c map[string]any) {
			c["experimental"].(map[string]any)["cache_file"] = map[string]any{"path": "/x"}
		},
		"external ui": func(c map[string]any) {
			c["experimental"].(map[string]any)["clash_api"].(map[string]any)["external_ui"] = "/x"
		},
		"public stats api": func(c map[string]any) {
			c["experimental"].(map[string]any)["clash_api"].(map[string]any)["external_controller"] = "0.0.0.0:9090"
		},
		"mixed inbound":  func(c map[string]any) { c["inbounds"] = []any{map[string]any{"type": "mixed", "listen": "0.0.0.0"}} },
		"second inbound": func(c map[string]any) { c["inbounds"] = append(c["inbounds"].([]any), map[string]any{"type": "tun"}) },
		"cert path": func(c map[string]any) {
			out0(c)["tls"] = map[string]any{"enabled": true, "certificate_path": "/root/x"}
		},
		"nested path":            func(c map[string]any) { out0(c)["tls"] = map[string]any{"ech": map[string]any{"config_path": "/x"}} },
		"path outside transport": func(c map[string]any) { out0(c)["path"] = "/x" },
		"rule set":               func(c map[string]any) { c["route"].(map[string]any)["rule_set"] = []any{} },
		"rule with rule_set":     func(c map[string]any) { addRule(c, map[string]any{"rule_set": "x", "outbound": "direct"}) },
		"odd rule action":        func(c map[string]any) { addRule(c, map[string]any{"action": "route-options"}) },
		"wireguard outbound": func(c map[string]any) {
			c["outbounds"] = append(c["outbounds"].([]any), map[string]any{"type": "wireguard"})
		},
		"dns server extra key": func(c map[string]any) { dns0(c)["path"] = "/x" },
		"dns rule with rule_set": func(c map[string]any) {
			c["dns"].(map[string]any)["rules"] = []any{map[string]any{"rule_set": "x", "server": "fake"}}
		},
	}
	for name, mutate := range cases {
		c := load(t, "auto.json")
		mutate(c)
		if err := validate(c); err == nil {
			t.Errorf("%s: accepted, want rejected", name)
		}
	}
}

func TestAllowsTransportPath(t *testing.T) {
	c := load(t, "auto.json")
	out0(c)["transport"] = map[string]any{"type": "ws", "path": "/ws"}
	if err := validate(c); err != nil {
		t.Fatal(err)
	}
}

func out0(c map[string]any) map[string]any { return c["outbounds"].([]any)[0].(map[string]any) }
func dns0(c map[string]any) map[string]any {
	return c["dns"].(map[string]any)["servers"].([]any)[0].(map[string]any)
}
func addRule(c map[string]any, r map[string]any) {
	rt := c["route"].(map[string]any)
	rt["rules"] = append(rt["rules"].([]any), r)
}

// --- protocol, with a fake core ---

type harness struct {
	sock, dir, marker string
}

func newHarness(t *testing.T, uid int) harness {
	t.Helper()
	dir := t.TempDir()
	h := harness{sock: filepath.Join(dir, "s"), dir: dir, marker: filepath.Join(dir, "termed")}
	core := filepath.Join(dir, "fake-core")
	script := "#!/bin/sh\necho started\ntrap 'echo > " + h.marker + "; exit 0' TERM\nwhile :; do sleep 0.05; done\n"
	if err := os.WriteFile(core, []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	l, err := net.Listen("unix", h.sock)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { l.Close() })
	go func() {
		for {
			c, err := l.Accept()
			if err != nil {
				return
			}
			go serve(c.(*net.UnixConn), uid, core, dir)
		}
	}()
	return h
}

func dial(t *testing.T, h harness, req any) (net.Conn, *bufio.Scanner) {
	t.Helper()
	c, err := net.Dial("unix", h.sock)
	if err != nil {
		t.Fatal(err)
	}
	b, _ := json.Marshal(req)
	c.Write(append(b, '\n'))
	return c, bufio.NewScanner(c)
}

func next(t *testing.T, c net.Conn, s *bufio.Scanner) map[string]any {
	t.Helper()
	c.SetReadDeadline(time.Now().Add(5 * time.Second))
	if !s.Scan() {
		t.Fatalf("no reply: %v", s.Err())
	}
	var m map[string]any
	json.Unmarshal(s.Bytes(), &m)
	return m
}

func waitFile(p string) bool {
	for i := 0; i < 60; i++ {
		if _, err := os.Stat(p); err == nil {
			return true
		}
		time.Sleep(50 * time.Millisecond)
	}
	return false
}

func TestStartStreamStop(t *testing.T) {
	h := newHarness(t, os.Getuid())
	c, s := dial(t, h, map[string]any{"cmd": "start", "config": load(t, "auto.json")})
	defer c.Close()
	if m := next(t, c, s); m["log"] != "started" {
		t.Fatalf("want log line, got %v", m)
	}
	c.Write([]byte(`{"cmd":"stop"}` + "\n"))
	if m := next(t, c, s); m["exit"] == nil {
		t.Fatalf("want exit, got %v", m)
	}
	if !waitFile(h.marker) {
		t.Fatal("core was not terminated")
	}
	// config written root-only
	if fi, err := os.Stat(filepath.Join(h.dir, "config.json")); err != nil || fi.Mode().Perm() != 0o600 {
		t.Fatalf("config perms: %v %v", fi, err)
	}
}

// App crash/quit = connection drops = core must stop.
func TestDisconnectStopsCore(t *testing.T) {
	h := newHarness(t, os.Getuid())
	c, s := dial(t, h, map[string]any{"cmd": "start", "config": load(t, "auto.json")})
	next(t, c, s)
	c.Close()
	if !waitFile(h.marker) {
		t.Fatal("core kept running after the app disconnected")
	}
}

func TestRejectsBadConfigOverSocket(t *testing.T) {
	h := newHarness(t, os.Getuid())
	cfg := load(t, "auto.json")
	cfg["log"].(map[string]any)["output"] = "/etc/passwd"
	c, s := dial(t, h, map[string]any{"cmd": "start", "config": cfg})
	defer c.Close()
	if m := next(t, c, s); !strings.Contains(m["error"].(string), "rejected") {
		t.Fatalf("want rejection, got %v", m)
	}
}

func TestOtherUserRefused(t *testing.T) {
	if os.Getuid() == 0 {
		t.Skip("root is always allowed")
	}
	h := newHarness(t, os.Getuid()+1)
	c, s := dial(t, h, map[string]any{"cmd": "version"})
	defer c.Close()
	if m := next(t, c, s); m["error"] != "not allowed" {
		t.Fatalf("want refusal, got %v", m)
	}
}

func TestVersion(t *testing.T) {
	h := newHarness(t, os.Getuid())
	c, s := dial(t, h, map[string]any{"cmd": "version"})
	defer c.Close()
	if m := next(t, c, s); m["version"] != version {
		t.Fatalf("got %v", m)
	}
}
